impl<'a, T               , G: SpinGuardian> RwLockUpgradeableGuard<'a, T, G> {
    #[verifier::exec_allows_no_decreases_clause]
    pub fn upgrade(            self) -> RwLockWriteGuard<'a, T, G> {
        let mut this = self;
